'use strict';

/**
* Compute the variance of a one-dimensional double-precision floating-point ndarray, ignoring `NaN` values.
*
* @module @stdlib/stats-base-ndarray-dnanvariance
*
* @example
* var Float64Vector = require( '@stdlib/ndarray-vector-float64' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var dnanvariance = require( '@stdlib/stats-base-ndarray-dnanvariance' );
*
* var opts = {
*     'dtype': 'float64'
* };
*
* // Define a one-dimensional input ndarray:
* var x = new Float64Vector( [ 1.0, -2.0, NaN, 2.0 ] );
*
* // Specify the degrees of freedom adjustment:
* var correction = scalar2ndarray( 1.0, opts );
*
* // Compute the variance:
* var v = dnanvariance( [ x, correction ] );
* // returns ~4.3333
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils-try-require' );
var isError = require( '@stdlib/assert-is-error' );
var main = require( './main.js' );


// MAIN //

var dnanvariance;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dnanvariance = main;
} else {
	dnanvariance = tmp;
}


// EXPORTS //

module.exports = dnanvariance;
